const users = [
  { id: 1, name: "Ada" },
  { id: 2, name: "Grace" },
];

const MAX_LIMIT = 100;

export function listUsers(limit = 20) {
  if (!Number.isInteger(limit) || limit < 1 || limit > MAX_LIMIT) {
    throw new RangeError(`limit must be an integer between 1 and ${MAX_LIMIT}`);
  }
  return users.slice(0, limit);
}

